mapper.update:
UPDATE T_ATM
ATM_STATUS = #{atmStatus}, ASSET_FLAG = #{assetFlag}, LOCATION_TYPE_CD = #{locationTypeCd}, LOCATION_NAME = #{locationName}, ATM_CO_CD = #{atmCoCd}, MODEL_CD = #{modelCd}, ATM_IP = #{atmIp}, BRANCH_CD = #{branchCd}, CORNER_CD = #{cornerCd}, APP_VERSION = #{appVersion},
WHERE TERM_GROUP_ID = #{termGroupId} AND TERM_ID = #{termId}

mapper.delete:
